from collections import Counter
import json
L,S=2048,512
out={}
for rows in (20,100):
 c=Counter(t for a in range(0,rows*S,S) for t in range(a+1,a+L))
 out[str(rows)]={'scored_positions_with_repeats':sum(c.values()),'unique_target_positions':len(c),'max_multiplicity':max(c.values()),'input_span_tokens':(rows-1)*S+L}
p=[0.7,0.2,0.1]; q=[0.68,0.22,0.10]; n=10000
metric=sum((a-b)**2/b for a,b in zip(q,p))
pearson=sum((n*a-n*b)**2/(n*b) for a,b in zip(q,p))
out['histogram_metric_example']={'probability_metric':metric,'count_Pearson_statistic':pearson,'ratio':pearson/metric}
print(json.dumps(out,sort_keys=True))

